test('adding three todos updates the remaining count', async ({ page }) => {
  await page.goto('/');

  const input = page.getByLabel('New todo');
  for (const text of ['buy milk', 'walk dog', 'write report']) {
    await input.fill(text);
    await input.press('Enter');
  }

  await expect(page.locator('#todo-list .todo-item')).toHaveCount(3);
  await expect(page.locator('#remaining-count')).toHaveText('3 items left');
});

test('toggling moves items between filters', async ({ page }) => {
  await seed(page, [
    { text: 'buy milk', done: false },
    { text: 'walk dog', done: true },
    { text: 'write report', done: false },
  ]);

  const listTexts = page.locator('#todo-list .text');

  // All filter: everything is visible.
  await page.getByRole('button', { name: 'All' }).click();
  await expect(listTexts).toHaveText(['buy milk', 'walk dog', 'write report']);

  // Active filter: only the two not-done items.
  await page.getByRole('button', { name: 'Active' }).click();
  await expect(listTexts).toHaveText(['buy milk', 'write report']);

  // Completed filter: only the done item.
  await page.getByRole('button', { name: 'Completed' }).click();
  await expect(listTexts).toHaveText(['walk dog']);

  // Toggle "buy milk" to done -> leaves Active...
  await page.getByRole('button', { name: 'All' }).click();
  await page.getByLabel('Toggle buy milk').check();
  await page.getByRole('button', { name: 'Active' }).click();
  await expect(listTexts).toHaveText(['write report']);

  // ...and appears under Completed.
  await page.getByRole('button', { name: 'Completed' }).click();
  await expect(listTexts).toHaveText(['buy milk', 'walk dog']);

  // Toggle "buy milk" back to active.
  await page.getByLabel('Toggle buy milk').uncheck();
  await expect(listTexts).toHaveText(['walk dog']);
});

test('deleting a todo removes it from the list and the count', async ({ page }) => {
  await seed(page, [
    { text: 'buy milk', done: false },
    { text: 'walk dog', done: false },
    { text: 'write report', done: false },
  ]);

  await page.getByLabel('Delete walk dog').click();

  await expect(page.locator('#todo-list .todo-item')).toHaveCount(2);
  const texts = page.locator('#todo-list .text');
  await expect(texts).toHaveText(['buy milk', 'write report']);
  await expect(page.locator('#remaining-count')).toHaveText('2 items left');
});

test('todos persist across reload', async ({ page }) => {
